# Hier muss worst/opt case umgetauscht werden. Beim worst case rbt gibt es ganz links einen Black-Black Pfad und ganz
# rechts einen alternierenden Black-Red-Black-Red ... Pfad. D.h. dieser rechte Pfad ist viel länger. Insertet man nun ganz
# rechts, dann muss natürlich mehr wieder zurecht gerichtet werden (d.h. das sollte eig worst case sein). Insertet man aber links,
# ist der Pfad viel kürzer (opt case).
# Bei delete bleibt alles gleich.

y_i_opt = []
y_i_worst = []
y_d_opt = []
y_d_worst = []

for i in range(5, 17):
    y_i_opt   += [sum(v[0] for v in data_comp[f"i_opt_{i}"]) / 5]
    y_i_worst += [sum(v[0] for v in data_comp[f"i_worst_{i}"]) / 5]
    y_d_opt   += [sum(v[0] for v in data_comp[f"d_opt{i}"]) / 5]
    y_d_worst += [sum(v[0] for v in data_comp[f"d_worst{i}"]) / 5]

fig3, ax3 = plt.subplots(figsize=(9, 7))
ax3.plot(range(5, 17), y_i_opt,   "blue",   label="insert worst", linestyle="dotted")
ax3.plot(range(5, 17), y_i_worst, "red",  label="insert optimal",linestyle="dotted")
ax3.plot(range(5, 17), y_d_opt,   "red", label="delete optimal", linestyle="dashed")
ax3.plot(range(5, 17), y_d_worst, "blue",label="delete worst", linestyle="dashed")
ax3.set_title("insert vs delete on worst case tree")
ax3.set_xlabel("tree depth")
ax3.set_ylabel("run time (seconds)")
ax3.set_xticks(range(5, 17))
ax3.legend()
plt.show()


